from pathlib import Path
import json,re,shutil,hashlib
R=Path(r"\\192.168.87.201\Projects\RicochetAngles\01_RND\ThreeJSDEV")
p=R/'spike/RicochetAngles_Legacy_ThreeJS_GLBSPIKE.html'
backup=p.with_name('RicochetAngles_Legacy_ThreeJS_GLBSPIKE.before_muzzle.html')
assert not backup.exists();shutil.copy2(p,backup)
s=p.read_text(encoding='utf-8')
s=s.replace('M41_RND_v01.glb','M41_RND_v02_muzzle.glb')
s=s.replace('<div id="glbStatus">','<label><input id="bridgeEnabled" type="checkbox" checked>Bridge 75ms</label> <label><input id="muzzleDebug" type="checkbox">Muzzle debug</label><div id="muzzleDelta" hidden></div>\n  <div id="glbStatus">',1)
s=s.replace("['M41_ROOT','HULL','TRACK_L','TRACK_R','TURRET_PIVOT','TURRET','GUN']","['M41_ROOT','HULL','TRACK_L','TRACK_R','TURRET_PIVOT','TURRET','GUN','MUZZLE']",1)
extension=json.loads(r'''"\n  // Presentation-only state: no properties are added to gameplay shells or particles.\n  const bridgeConfig={enabled:true,duration:.075,debug:false};\n  const bridgeStates=new Map();\n  let hiddenMuzzleParticles=new WeakSet(),bridgeGame=game;\n  const bridgeMetrics={deltaLogicalPx:0,deltaCssPx:0,lastRemoval:null};\n  const flash=new THREE.Mesh(sphere,new THREE.MeshBasicMaterial({color:0xffedac,transparent:true,depthWrite:false,depthTest:false}));\n  const smoke=new THREE.Mesh(sphere,new THREE.MeshBasicMaterial({color:0xa6a8a3,transparent:true,opacity:0,depthWrite:false}));\n  flash.name='PLAYER_MUZZLE_FLASH';smoke.name='PLAYER_MUZZLE_SMOKE';\n  flash.visible=smoke.visible=false;flash.renderOrder=11;scene.add(flash,smoke);\n  let shotFX=null;\n  function resetBridgeIfNeeded(){\n    if(bridgeGame===game)return;\n    bridgeGame=game;bridgeStates.clear();hiddenMuzzleParticles=new WeakSet();\n    rendererSpike.hiddenMuzzleParticles=hiddenMuzzleParticles;shotFX=null;\n    flash.visible=smoke.visible=false;\n  }\n  function muzzlePosition(){\n    if(!glbPlayer)return null;\n    syncPlayerVisual();glbPlayer.updateMatrixWorld(true);\n    return glbPlayer.getObjectByName('MUZZLE').getWorldPosition(new THREE.Vector3());\n  }\n  function capturePlayerFire(shell,particles){\n    resetBridgeIfNeeded();\n    const origin=muzzlePosition();if(!origin)return;\n    const direction=new THREE.Vector3(1,0,0).transformDirection(glbPlayer.getObjectByName('MUZZLE').matrixWorld);\n    bridgeStates.set(shell,{start:origin.clone(),born:game.time,ricochetCount:shell.ricochetCount,bridge:bridgeConfig.enabled});\n    particles.forEach(p=>hiddenMuzzleParticles.add(p));\n    shotFX={origin,direction,born:game.time};\n  }\n  function syncMuzzleFX(){\n    resetBridgeIfNeeded();\n    if(!shotFX){flash.visible=smoke.visible=false;return;}\n    const age=Math.max(0,game.time-shotFX.born);\n    flash.visible=age<.055;flash.position.copy(shotFX.origin);\n    flash.scale.setScalar(3.5+age*20);flash.material.opacity=Math.max(0,1-age/.055);\n    smoke.visible=age<.24;\n    smoke.position.copy(shotFX.origin).addScaledVector(shotFX.direction,age*14);\n    smoke.position.y+=age*7;smoke.scale.setScalar(2.5+age*25);\n    smoke.material.opacity=.28*Math.max(0,1-age/.24);\n    if(age>=.24)shotFX=null;\n  }\n  function projectMuzzle(){\n    const origin=muzzlePosition();if(!origin)return null;\n    const p=origin.project(view);\n    return {x:(p.x+1)*W/2,y:(1-p.y)*H/2};\n  }\n  function drawMuzzleDebug(sx,sy){\n    const label=document.getElementById('muzzleDelta');\n    if(!bridgeConfig.debug||!rendererSpike.enabled||!glbPlayer){label.hidden=true;return;}\n    const green=projectMuzzle();if(!green)return;\n    const p=game.player,d=TUNING.playerShellMuzzleDistance;\n    const red={x:p.x+Math.cos(p.turretAngle)*d-camera.x+sx,y:p.y+Math.sin(p.turretAngle)*d-camera.y+sy};\n    const dx=green.x-red.x,dy=green.y-red.y,rect=canvas.getBoundingClientRect();\n    bridgeMetrics.deltaLogicalPx=Math.hypot(dx,dy);\n    bridgeMetrics.deltaCssPx=Math.hypot(dx*rect.width/W,dy*rect.height/H);\n    bridgeMetrics.green=green;bridgeMetrics.red=red;\n    label.hidden=false;label.textContent='Muzzle Screen Delta: '+bridgeMetrics.deltaCssPx.toFixed(2)+' px (CSS)';\n    ctx.save();ctx.strokeStyle='#ccdda9';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(red.x,red.y);ctx.lineTo(green.x,green.y);ctx.stroke();\n    [[red,'#ff5555'],[green,'#4dff80']].forEach(([p,c])=>{ctx.fillStyle=c;ctx.beginPath();ctx.arc(p.x,p.y,3,0,TAU);ctx.fill();});\n    ctx.restore();\n  }\n  document.getElementById('bridgeEnabled').onchange=e=>{bridgeConfig.enabled=e.target.checked;};\n  document.getElementById('muzzleDebug').onchange=e=>{bridgeConfig.debug=e.target.checked;};\n"''')
s=s.replace('  function syncProjectileVisuals() {',extension+'\n  function syncProjectileVisuals() {',1)
projectile=json.loads(r'''"\n  function syncProjectileVisuals() {\n    resetBridgeIfNeeded();\n    const current=new Set(game.shells.filter(s=>!s.dead));\n    for(const [state,m] of shells) if(!current.has(state)) {\n      // A collision can occur before 75 ms. End the bridge at the authoritative hit,\n      // then hide/recycle the shell; original Canvas impact is left untouched.\n      m.position.set(state.x,0,state.y);\n      if(bridgeStates.has(state))bridgeMetrics.lastRemoval={x:state.x,y:state.y,dead:state.dead};\n      m.visible=false;shells.delete(state);shellPool.push(m);bridgeStates.delete(state);\n    }\n    for(const state of bridgeStates.keys())if(!current.has(state))bridgeStates.delete(state);\n    for(const s of current) {\n      let m=shells.get(s);\n      if(!m) {m=shellPool.pop()||new THREE.Mesh(sphere,shellMaterials[s.owner]);scene.add(m);shells.set(s,m);}\n      m.visible=true;m.renderOrder=10;m.material=shellMaterials[s.owner];m.position.set(s.x,8,s.y);m.scale.set(6,3,3);\n      const bridge=bridgeStates.get(s);\n      if(bridge){\n        const age=Math.max(0,game.time-bridge.born);\n        if(s.ricochetCount!==bridge.ricochetCount)bridge.bridge=false;\n        if(bridge.bridge&&bridgeConfig.enabled&&age<bridgeConfig.duration)\n          m.position.lerpVectors(bridge.start,m.position.clone(),age/bridgeConfig.duration);\n      }\n      m.rotation.y=-Math.atan2(s.vy,s.vx);\n    }\n  }\n"''')
s,n=re.subn(r'  function syncProjectileVisuals\(\) \{.*?(?=  function syncCamera)',lambda _:projectile+'\n',s,count=1,flags=re.S);assert n==1
s=s.replace('syncProjectileVisuals(); syncCamera(sx,sy);','syncProjectileVisuals(); syncMuzzleFX(); syncCamera(sx,sy);',1)
s=s.replace('playerVisual,bossVisual,stressTanks,stressGroup,addStressTank,','playerVisual,bossVisual,stressTanks,stressGroup,addStressTank,\n    capturePlayerFire,hiddenMuzzleParticles,drawMuzzleDebug,\n    muzzleBridge:{config:bridgeConfig,states:bridgeStates,metrics:bridgeMetrics,flash,smoke,muzzlePosition,shells},',1)
# Drawing-only classic script changes. Particle simulation stays untouched.
s=s.replace('    var p = game.particles[i], a = clamp(p.life / p.maxLife, 0, 1);','    var p = game.particles[i], a = clamp(p.life / p.maxLife, 0, 1);\n    if(rendererSpike && rendererSpike.enabled && rendererSpike.hiddenMuzzleParticles && rendererSpike.hiddenMuzzleParticles.has(p)) continue;',1)
s=s.replace('  drawUI(); drawDebug(); drawCrosshair();','  drawUI(); drawDebug(); drawCrosshair();\n  if(rendererSpike && rendererSpike.enabled && rendererSpike.drawMuzzleDebug) rendererSpike.drawMuzzleDebug(sx,sy);',1)
# Observe original fire result, including shots killed by collision before their first rendered frame.
s=s.replace('  loadM41();',r'''
  const legacyFireShell=window.fireShell;
  window.fireShell=function(tank,owner){
    const particleStart=game.particles.length;
    const result=legacyFireShell.apply(this,arguments);
    if(owner==='player'&&rendererSpike.enabled&&glbPlayer){
      try{withVisualRandom(()=>capturePlayerFire(game.shells[game.shells.length-1],game.particles.slice(particleStart)));}
      catch(error){console.warn('Muzzle presentation capture failed',error);}
    }
    return result;
  };
  loadM41();''',1)
p.write_text(s,encoding='utf-8')
# Original simulation and fire functions remain text-identical, including updates through the rendering boundary.
old=backup.read_text(encoding='utf-8')
a=old.split('<script>')[1].split('// 렌더링')[0]
b=s.split('<script>')[1].split('// 렌더링')[0]
assert a==b
(R/'M41/notes/muzzle_code_validation.json').write_text(json.dumps({'simulation_source_identical':True,'backup_sha256':hashlib.sha256(backup.read_bytes()).hexdigest(),'presentation_changes':['drawEffects skips observed player muzzle particles only in 3D','render draws optional anchor debug','post-call fireShell observer invokes original unchanged']},indent=2))
print('Patched; simulation source identical; backup preserved')

